/** Local visual fixture generated by the real damage/reaction rules, never persisted. */
import { DEFAULT_CONTENT, SCENARIOS_BY_ID, type GameEvent, type GameState } from '../../../game';
import { shapeshifterCatalog } from '../../../game/data/shapeshifter-catalog';
import { createShapeshifterBattle } from '../../../game/qa/shapeshifter-battle';
import { dealDamage } from '../../../game/domain/combat/damage';
import { SHOWCASE_UNIT } from './showcase';
export type CounterCase = 'single' | 'multiple' | 'defender-death' | 'attacker-death' | 'shield' | 'armor';
export function counterFeedback(form: 'bear' | 'minotaur', variant: CounterCase = 'single') {
  const content = { ...shapeshifterCatalog(DEFAULT_CONTENT),
    qaCombatDepth: { version: 1 as const, backstab: false, formCounter: 'perHit' as const } };
  const scenario = SCENARIOS_BY_ID.first_blood!;
  const state = structuredClone(createShapeshifterBattle(
    { ...scenario, hero: { ...scenario.hero, heroId: 'shapeshifter' } }, content, 13, 'guaranteed',
  ).state) as GameState;
  const hero = state.units.find(u => u.kind === 'HERO')!, enemy = state.units.find(u => u.kind === 'ENEMY')!;
  hero.id = SHOWCASE_UNIT; state.player.heroId = hero.id;
  hero.activeForm = form; hero.hp = hero.maxHp = 18; hero.armor = 0;
  hero.pos = {x:2,y:2}; hero.combatFacing = 'RIGHT'; hero.statuses = [];
  enemy.hp = enemy.maxHp = 8; enemy.armor = 0; enemy.shield = 0; enemy.statuses = [];
  enemy.pos = {x:3,y:2}; enemy.combatFacing = 'LEFT';
  state.units = [hero, enemy]; state.intents = []; state.obstacles = []; state.collectibles = [];
  if (variant === 'defender-death') hero.hp = 1;
  if (variant === 'attacker-death') enemy.hp = 1;
  if (variant === 'shield') enemy.shield = 2;
  if (variant === 'armor') enemy.armor = 2;
  const before = structuredClone(state), events: GameEvent[] = [];
  const ctx = {state,content,emit:(e:GameEvent)=>events.push(e)};
  for (let i=0;i<(variant === 'multiple'?2:1);i++) {
    if (!state.units.includes(hero) || !state.units.includes(enemy)) break;
    events.push({type:'ENEMY_ACTION_STARTED',enemyId:enemy.id,
      intent:{kind:'MELEE_ATTACK',enemyId:enemy.id,targetUnitId:hero.id,damage:3}});
    events.push({type:'ENEMY_ATTACKED',enemyId:enemy.id,intentKind:'MELEE_ATTACK',
      tiles:[hero.pos],targetUnitIds:[hero.id],damageType:'PHYSICAL'});
    dealDamage(ctx,hero,3,enemy.id,'PHYSICAL','DIRECT_MELEE');
    events.push({type:'ENEMY_ACTION_ENDED',enemyId:enemy.id});
  }
  return {before,after:state,events,content};
}
